import React, { useState } from "react";
import axios from "axios";

function App() {
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState("");
  const [loading, setLoading] = useState(false);

  const handleAsk = async () => {
    if (!prompt.trim()) {
      setResponse("❗ Please enter a question.");
      return;
    }

    setLoading(true);
    setResponse("");

    try {
      console.log("🟡 Sending request to backend with prompt:", prompt);
      const res = await axios.post("http://localhost:5000/ask", { prompt });

      console.log("🟢 Response from backend:", res.data);
      setResponse(res.data.answer || "⚠️ No response generated.");
    } catch (error) {
      console.error("🔴 Error from frontend:", error.message);
      setResponse("❌ Failed to get a response. Try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: 40 }}>
      <h2>🧠 Ask the AI Assistant</h2>
      <textarea
        value={prompt}
        onChange={(e) => setPrompt(e.target.value)}
        rows="5"
        cols="50"
        placeholder="Type your question here..."
      />
      <br />
      <button onClick={handleAsk} style={{ marginTop: 10 }}>
        Ask
      </button>
      <div style={{ marginTop: 20 }}>
        <strong>Response:</strong>
        <p>{loading ? "⏳ Loading..." : response}</p>
      </div>
    </div>
  );
}

export default App;
